class Solution {
  public int getLength(int[] nums) {
    int n = nums.length;
    int[] sorted = nums.clone();
    java.util.Arrays.sort(sorted);
    int m = 0;
    for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
    int[] id = new int[n];
    for (int i = 0; i < n; i++) id[i] = java.util.Arrays.binarySearch(sorted, 0, m, nums[i]);
    int best = 1;
    for (int l = 0; l < n; l++) {
      int[] freq = new int[m], cntOfFreq = new int[n + 2];
      int distinct = 0, maxF = 0;
      for (int r = l; r < n; r++) {
        int v = id[r];
        if (freq[v] == 0) distinct++;
        else cntOfFreq[freq[v]]--;
        freq[v]++;
        cntOfFreq[freq[v]]++;
        maxF = Math.max(maxF, freq[v]);
        boolean ok =
            distinct == 1
                || (maxF % 2 == 0
                    && cntOfFreq[maxF / 2] > 0
                    && cntOfFreq[maxF] > 0
                    && cntOfFreq[maxF / 2] + cntOfFreq[maxF] == distinct);
        if (ok) best = Math.max(best, r - l + 1);
      }
    }
    return best;
  }
}
